  const keys = [[0, { Rg: 'open', RgFlip: 0, Rx: 444, Ry: 250, Rr: -88, bY: -3, ms: 0.65, lx: 0.12, px: 0.05, py: 0.25, happy: 0, wink: 0 }]];
