__m['pos-bridge'] = (() => {
// POS → mascot bridge.
// The mascot knows nothing about sales or cash registers. This module is the
// only place where business events are translated into reactions and copy,
// so product decides tone and frequency here without touching the animation.
//
//   const bridge = createPosBridge(mascot);
//   bridge.emit('payment.approved', { total: 245.5, method: 'tarjeta' });

const money = n => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format(Number(n) || 0);

/** Default mapping. Each rule returns { state, message?, clear? } or null to ignore. */
const DEFAULT_RULES = {
  'session.login': e => ({ state: 'GREETING', message: e.cashier ? `¡Hola, ${e.cashier}! ¿Abrimos caja?` : undefined }),
  'session.logout': () => ({ state: 'GOODBYE' }),
  'sale.item_added': () => null, // too frequent: never react to every scan
  'payment.processing': e => ({ state: 'THINKING', message: e.method === 'tarjeta' ? 'Esperando la terminal…' : null }),
  'payment.approved': e => ({ clear: 'THINKING', state: 'SALE_SUCCESS', message: `¡Venta cobrada! ${money(e.total)}` }),
  'payment.declined': e => ({ clear: 'THINKING', state: 'ERROR', message: e.reason ? `Pago rechazado: ${e.reason}. Prueba otro método.` : 'El pago fue rechazado. Prueba otro método.' }),
  'refund.completed': e => ({ state: 'HAPPY', message: `Devolución registrada: ${money(e.total)}` }),
  'inventory.low': e => ({ state: 'WARNING', message: `Quedan ${e.qty} de ${e.product}. Conviene resurtir.` }),
  'manager.approval_required': e => ({ state: 'WARNING', message: e.reason ? `${e.reason}: necesita autorización de un gerente.` : 'Esta acción necesita autorización de un gerente.' }),
  'manager.approved': () => ({ state: 'HAPPY', message: 'Autorizado. ¡Seguimos!' }),
  'cash.closing_started': () => ({ state: 'TALKING', message: 'Vamos con el corte de caja. Cuenta el efectivo con calma.' }),
  'cash.closed': e => Math.abs(e.difference || 0) < 0.01
    ? { state: 'CELEBRATION', message: '¡Corte cuadrado al centavo!' }
    : { state: 'WARNING', message: `El corte tiene una diferencia de ${money(e.difference)}.` },
  'network.offline': () => ({ state: 'OFFLINE' }),
  'network.online': () => ({ clear: 'OFFLINE', state: 'HAPPY', message: 'Conexión de vuelta. Sincronizando ventas…' }),
  'sales.milestone': e => ({ state: 'CELEBRATION', message: `¡${e.count} ventas hoy! ¡Eres lo máximo!` }),
  'achievement.unlocked': e => ({ state: 'CELEBRATION', message: `¡Logro desbloqueado: ${e.title}!` }),
  'tip': e => ({ state: 'TALKING', message: e.text }),
  'system.error': e => ({ state: 'ERROR', message: e.message }),
};

/**
 * @param {object} mascot   instance from createMascot()
 * @param {object} [opts]
 * @param {object} [opts.rules]        override or add event rules
 * @param {number} [opts.cooldownMs]   minimum time between reactions of the same event (default 1500)
 * @param {() => boolean} [opts.isQuiet]  return true to silence non-critical reactions (e.g. PIN entry)
 */
function createPosBridge(mascot, opts = {}) {
  const rules = { ...DEFAULT_RULES, ...(opts.rules || {}) };
  const cooldown = opts.cooldownMs ?? 1500;
  const lastAt = new Map();
  const CRITICAL = new Set(['ERROR', 'OFFLINE', 'WARNING']);
  let enabled = true;

  function emit(type, payload = {}) {
    if (!enabled) return null;
    const rule = rules[type];
    if (!rule) return null;
    const t = performance.now();
    if (t - (lastAt.get(type) || -1e9) < cooldown) return null;
    const r = rule(payload);
    if (!r) return null;
    if (opts.isQuiet && opts.isQuiet() && !CRITICAL.has(r.state)) return null;
    lastAt.set(type, t);
    if (r.clear) mascot.clear(r.clear);
    const o = {};
    if (r.message !== undefined) o.message = r.message;
    return r.state ? mascot.react(r.state, o) : null;
  }

  return {
    emit,
    enable() { enabled = true; },
    disable() { enabled = false; },
    rules,
  };
}

return { DEFAULT_RULES, createPosBridge };
})();

